contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address receiver, uint amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint beforeC = address(c).balance;
        uint beforeReceiver = receiver.balance;

        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterC = address(c).balance;
        uint afterReceiver = receiver.balance;

        assert(
            (reverted && afterC == beforeC && afterReceiver == beforeReceiver) ||
            (!reverted && afterC + amount == beforeC && afterReceiver == beforeReceiver + amount)
        );
    }
}

